import React, { useState, useEffect } from 'react';
import { uploadFile, getFiles, downloadFile, deleteFile } from '../services/api';
import CryptoFlow from '../components/CryptoFlow';
import { Upload, Download, FileText, AlertTriangle, Server, HardDrive, Terminal, Trash2, Activity, Play, X } from 'lucide-react';
import { Bar } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend } from 'chart.js';

// Register ChartJS
ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const Dashboard = () => {
  const [files, setFiles] = useState([]);
  const [fileToUpload, setFileToUpload] = useState(null); // Staging state
  const [uploadStep, setUploadStep] = useState(0); 
  const [error, setError] = useState(null);
  const [logs, setLogs] = useState([]); 
  const [selectedFile, setSelectedFile] = useState(null); 
  const [showDeleteModal, setShowDeleteModal] = useState(null); // File ID to delete

  // Toggles
  const [storageMode, setStorageMode] = useState('local');
  const [cryptoMode, setCryptoMode] = useState('hybrid'); 

  useEffect(() => {
    fetchFiles();
  }, []);

  const addLog = (msg) => {
    const timestamp = new Date().toLocaleTimeString('en-US', { hour12: false });
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const fetchFiles = async () => {
    try {
      const res = await getFiles();
      setFiles(res.data);
    } catch (err) { console.error("Fetch failed"); }
  };

  // --- DELETE LOGIC ---
  const confirmDelete = async () => {
      if (!showDeleteModal) return;
      try {
          await deleteFile(showDeleteModal);
          addLog(`WARN: File ID ${showDeleteModal} permanently erased.`);
          fetchFiles();
          if (selectedFile?.id === showDeleteModal) setSelectedFile(null);
      } catch (err) {
          setError("Delete failed.");
      }
      setShowDeleteModal(null);
  };

  // --- UPLOAD STAGING ---
  const onFileDrop = (e) => {
      const file = e.target.files[0];
      if (file) {
          setFileToUpload(file);
          setError(null);
          addLog(`STAGE: ${file.name} loaded. Waiting for encryption sequence...`);
      }
  };

  const startEncryption = async () => {
    if (!fileToUpload) return;

    setUploadStep(1);
    setLogs([]); 
    setSelectedFile(null); 
    
    addLog(`INIT: Starting Secure Protocol for ${fileToUpload.name}`);
    addLog(`MODE: ${cryptoMode === 'hybrid' ? 'Hybrid (Kyber-512 + AES-256)' : 'Baseline (RSA-2048)'}`);

    // Animation Timing
    if (cryptoMode === 'hybrid') {
        setTimeout(() => { setUploadStep(2); addLog("PQC: Generating Ephemeral Keys..."); }, 600);
        setTimeout(() => { setUploadStep(3); addLog("PQC: Encapsulating Shared Secret..."); }, 1200);
    } else {
        setTimeout(() => { addLog("RSA: Generating Classical Keypair..."); }, 600);
    }
    
    setTimeout(() => { setUploadStep(4); addLog("KDF: Deriving High-Entropy Session Key..."); }, 1800);

    try {
      // API Call
      const res = await uploadFile(fileToUpload, cryptoMode); 
      
      setUploadStep(5);
      addLog("AES: Encrypting Payload (GCM Mode)...");
      addLog("NET: Uploading Encrypted Blob...");
      
      setTimeout(() => {
        setUploadStep(0);
        setFileToUpload(null); // Clear Staging
        addLog(`SUCCESS: File Sealed. ID: ${res.data.file_id}`);
        fetchFiles();
      }, 1200);
    } catch (err) {
      setUploadStep(0);
      addLog("ERROR: Protocol Failed.");
      setError("Upload Failed. Check backend connection.");
    }
  };

  // --- DOWNLOAD LOGIC ---
  const handleDownload = async (file) => {
    if (file.mode !== 'hybrid') {
        setError("BASELINE RESTRICTION: Switch to Hybrid Mode to enable PQC Decryption.");
        return;
    }

    try {
      addLog(`REQ: Download Request for ${file.filename}`);
      await downloadFile(file.id, file.filename);
      addLog("SUCCESS: Integrity Verified & Decrypted.");
    } catch (err) {
      addLog("❌ FAILURE: Integrity Check Failed.");
      setError("CRITICAL: Ciphertext Tag Mismatch. The cloud file differs from the signature.");
    }
  };

  // --- CHART CONFIG ---
  const getChartData = (metrics) => ({
      labels: ['PQC Encap', 'AES Encrypt', 'Total Latency'],
      datasets: [{
          label: 'Time (ms)',
          data: [metrics.pqc, metrics.aes, metrics.total],
          backgroundColor: ['#00ff9d', '#00f3ff', '#ffffff'],
          borderColor: ['#00ff9d', '#00f3ff', '#ffffff'],
          borderWidth: 1
      }]
  });

  return (
    <div className="p-8 space-y-6 relative">
      
      {/* DELETE MODAL */}
      {showDeleteModal && (
          <div className="fixed inset-0 bg-black/80 flex items-center justify-center z-50 backdrop-blur-sm">
              <div className="bg-scifi-panel border border-red-500 p-6 rounded-xl w-96 shadow-[0_0_30px_rgba(255,0,0,0.2)]">
                  <h3 className="text-xl font-bold text-red-500 mb-2 flex items-center gap-2">
                      <AlertTriangle /> Confirm Deletion
                  </h3>
                  <p className="text-gray-400 text-sm mb-6">
                      Are you sure you want to destroy this file from the Vault? This action cannot be undone.
                  </p>
                  <div className="flex justify-end gap-3">
                      <button onClick={() => setShowDeleteModal(null)} className="px-4 py-2 rounded border border-gray-600 hover:bg-white/10 text-gray-300 text-xs uppercase font-bold">Cancel</button>
                      <button onClick={confirmDelete} className="px-4 py-2 rounded bg-red-600 hover:bg-red-700 text-black text-xs uppercase font-bold">Destroy File</button>
                  </div>
              </div>
          </div>
      )}

      {/* HEADER */}
      <div className="flex justify-between items-end">
        <div>
          <h2 className="text-2xl font-bold text-white mb-2">Secure Gateway</h2>
          <p className="text-gray-400 text-sm">Post-Quantum Cryptography Enabled</p>
        </div>
        <div className="flex gap-4">
            <div className="flex flex-col items-end">
                <label className="text-[10px] text-gray-500 uppercase mb-1">Experiment Mode</label>
                <select 
                    value={cryptoMode} 
                    onChange={(e) => setCryptoMode(e.target.value)}
                    className="bg-scifi-panel border border-scifi-border text-xs text-neon-blue p-2 rounded focus:outline-none"
                >
                    <option value="hybrid">Hybrid (PQC + AES)</option>
                    <option value="rsa">RSA-2048 (Baseline)</option>
                </select>
            </div>
            <div className="flex flex-col items-end">
                <label className="text-[10px] text-gray-500 uppercase mb-1">Storage Backend</label>
                <button 
                    onClick={() => setStorageMode(storageMode === 'local' ? 'minio' : 'local')}
                    className="flex items-center gap-2 bg-scifi-panel border border-scifi-border text-xs text-neon-green p-2 rounded hover:bg-white/5"
                >
                    {storageMode === 'local' ? <HardDrive size={14} /> : <Server size={14} />}
                    {storageMode === 'local' ? 'Local FS' : 'MinIO'}
                </button>
            </div>
        </div>
      </div>

      {error && (
        <div className="bg-red-900/20 border border-red-500 p-4 rounded text-red-500 font-bold text-sm flex items-center gap-3">
            <AlertTriangle /> {error}
        </div>
      )}

      <div className="grid grid-cols-3 gap-6">
        
        {/* LEFT COLUMN */}
        <div className="col-span-2 space-y-6">
            
            {/* UPLOAD & STAGING AREA */}
            <div className="bg-scifi-panel border border-scifi-border rounded-xl p-6 relative overflow-hidden">
                <h3 className="text-white font-bold mb-4 flex items-center gap-2"><Upload size={18} /> Secure Upload</h3>
                
                {uploadStep > 0 ? (
                    <CryptoFlow currentStep={uploadStep} />
                ) : !fileToUpload ? (
                    <div className="border-2 border-dashed border-gray-700 rounded-lg p-10 text-center hover:border-neon-green transition-colors cursor-pointer relative group">
                        <input type="file" onChange={onFileDrop} className="absolute inset-0 opacity-0 cursor-pointer" />
                        <div className="group-hover:scale-105 transition-transform">
                            <Upload className="mx-auto text-gray-500 group-hover:text-neon-green mb-3" size={32} />
                            <p className="text-white font-bold">Drop files to Stage</p>
                            <p className="text-xs text-gray-500 mt-1">Ready for PQC-KEM Encap</p>
                        </div>
                    </div>
                ) : (
                    <div className="border border-neon-green/30 bg-neon-green/5 rounded-lg p-8 text-center animate-pulse-fast">
                        <FileText className="mx-auto text-neon-green mb-3" size={40} />
                        <p className="text-xl font-bold text-white mb-1">{fileToUpload.name}</p>
                        <p className="text-xs text-gray-400 mb-6">{(fileToUpload.size / 1024).toFixed(2)} KB • Ready for Encryption</p>
                        
                        <div className="flex justify-center gap-4">
                            <button onClick={() => setFileToUpload(null)} className="px-6 py-2 rounded border border-gray-600 text-gray-300 hover:bg-white/10 uppercase font-bold text-xs">
                                Cancel
                            </button>
                            <button onClick={startEncryption} className="px-6 py-2 rounded bg-neon-green text-black hover:bg-white hover:shadow-[0_0_20px_rgba(0,255,157,0.4)] uppercase font-bold text-xs flex items-center gap-2 transition-all">
                                <Play size={14} fill="black" /> Encrypt & Upload
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* TERMINAL */}
            <div className="bg-black border border-gray-800 rounded-xl p-4 h-48 overflow-y-auto font-mono text-xs shadow-inner">
                <div className="flex items-center gap-2 text-gray-500 border-b border-gray-800 pb-2 mb-2 sticky top-0 bg-black">
                    <Terminal size={14} /> CRYPTO_KERNEL_LOGS
                </div>
                {logs.map((log, i) => <p key={i} className="text-neon-green/80 mb-1 font-mono tracking-tight">{log}</p>)}
                {logs.length === 0 && <p className="text-gray-800 italic">System Idle. Waiting for input...</p>}
            </div>
            
            {/* SELECTED FILE REPORT & GRAPH */}
            {selectedFile && (
                <div className="bg-scifi-panel border border-neon-blue/30 rounded-xl p-6 animate-in fade-in slide-in-from-bottom-4 duration-500">
                    <div className="flex justify-between items-start mb-4">
                        <h4 className="text-neon-blue font-bold flex items-center gap-2">
                            <Activity size={18} /> Performance Metrics: {selectedFile.filename}
                        </h4>
                        <button onClick={() => setSelectedFile(null)} className="text-gray-500 hover:text-white"><X size={16}/></button>
                    </div>

                    <div className="grid grid-cols-2 gap-8">
                        {/* Text Stats */}
                        <div className="space-y-3">
                             <div className="flex justify-between border-b border-gray-800 pb-1">
                                <span className="text-gray-500 text-xs">Algorithm Mode</span>
                                <span className="text-white text-xs font-bold uppercase">{selectedFile.mode}</span>
                             </div>
                             <div className="flex justify-between border-b border-gray-800 pb-1">
                                <span className="text-gray-500 text-xs">PQC Encap Time</span>
                                <span className="text-neon-green text-xs font-mono">{selectedFile.metrics.pqc.toFixed(3)} ms</span>
                             </div>
                             <div className="flex justify-between border-b border-gray-800 pb-1">
                                <span className="text-gray-500 text-xs">AES Encrypt Time</span>
                                <span className="text-neon-blue text-xs font-mono">{selectedFile.metrics.aes.toFixed(3)} ms</span>
                             </div>
                             <div className="flex justify-between border-b border-gray-800 pb-1">
                                <span className="text-gray-500 text-xs">Total Latency</span>
                                <span className="text-white text-xs font-mono">{selectedFile.metrics.total.toFixed(3)} ms</span>
                             </div>
                        </div>

                        {/* Graph */}
                        <div className="h-32">
                            <Bar 
                                data={getChartData(selectedFile.metrics)} 
                                options={{
                                    responsive: true,
                                    maintainAspectRatio: false,
                                    plugins: { legend: { display: false } },
                                    scales: {
                                        y: { grid: { color: '#333' }, ticks: { color: '#666', font: {size: 8} } },
                                        x: { grid: { display: false }, ticks: { color: '#999', font: {size: 9} } }
                                    }
                                }} 
                            />
                        </div>
                    </div>
                </div>
            )}
        </div>

        {/* RIGHT COLUMN: FILE LIST */}
        <div className="col-span-1 bg-scifi-panel border border-scifi-border rounded-xl p-6 flex flex-col h-[600px]">
            <h3 className="text-white font-bold mb-4">Vault Contents</h3>
            <div className="space-y-2 overflow-y-auto custom-scrollbar flex-1 pr-2">
                {files.length === 0 && <p className="text-gray-600 text-center text-xs mt-10">Vault Empty</p>}
                {files.map(file => (
                    <div 
                        key={file.id} 
                        onClick={() => setSelectedFile(file)} 
                        className={`p-3 rounded border transition cursor-pointer group relative
                            ${selectedFile?.id === file.id ? 'bg-neon-blue/10 border-neon-blue' : 'bg-white/5 border-transparent hover:border-gray-600'}`}
                    >
                        <div className="flex justify-between items-start">
                            <p className="text-xs text-white truncate w-32 font-bold mb-1">{file.filename}</p>
                            <span className={`text-[9px] px-1.5 py-0.5 rounded font-bold uppercase tracking-wide
                                ${file.mode === 'hybrid' ? 'text-neon-green bg-neon-green/10' : 'text-neon-purple bg-neon-purple/10'}`}>
                                {file.mode === 'hybrid' ? 'PQC' : 'RSA'}
                            </span>
                        </div>
                        
                        <p className="text-[10px] text-gray-500">{new Date(file.date).toLocaleDateString()}</p>

                        <div className="absolute right-2 top-2 flex gap-2 opacity-0 group-hover:opacity-100 transition-opacity bg-black/80 p-1 rounded">
                             <button onClick={(e) => { e.stopPropagation(); setShowDeleteModal(file.id); }} className="text-red-500 hover:text-white p-1">
                                <Trash2 size={14} />
                            </button>
                            <button onClick={(e) => { e.stopPropagation(); handleDownload(file); }} className="text-neon-blue hover:text-white p-1">
                                <Download size={14} />
                            </button>
                        </div>
                    </div>
                ))}
            </div>
        </div>

      </div>
    </div>
  );
};

export default Dashboard;
